import XCTest

/// Generated by amoo from the Studio test "SwipeDelete". Edit freely — this file has no
/// dependency on amoo or the companion apps once generated.
@MainActor
final class SwipeDeleteTest: XCTestCase {
    private let defaultTimeout: TimeInterval = 5
    /// This test's own data set on the backend, so tests running at the same time
    /// don't see each other's changes.
    private let authSession = UUID().uuidString.lowercased()
    /// Calls one of the backend's test routes and returns the status, 0 when it did not answer.
    private func authCall(_ method: String, _ path: String) throws -> Int {
        var request = URLRequest(url: try XCTUnwrap(URL(string: "http://127.0.0.1:8081" + path)))
        request.httpMethod = method
        request.timeoutInterval = 10
        request.setValue(authSession, forHTTPHeaderField: "X-Test-Session")
        let done = DispatchSemaphore(value: 0)
        nonisolated(unsafe) var status = 0
        URLSession.shared.dataTask(with: request) { _, response, _ in
            status = (response as? HTTPURLResponse)?.statusCode ?? 0
            done.signal()
        }.resume()
        done.wait()
        return status
    }
    /// Calls one of the backend's test routes and fails the test unless it answers 2xx.
    private func authExpect(
        _ method: String, _ path: String, file: StaticString = #filePath, line: UInt = #line
    ) throws {
        let status = try authCall(method, path)
        XCTAssertTrue(
            (200..<300).contains(status), "\(method) \(path) answered \(status)", file: file, line: line)
    }
    private lazy var app = XCUIApplication()

    override func setUpWithError() throws {
        try super.setUpWithError()
        continueAfterFailure = false
        app.launchEnvironment["APP_TEST_SESSION"] = "\(authSession)"
        app.launchEnvironment["APP_BASE_URL"] = "http://127.0.0.1:8081"
        app.launch()
    }

    override func tearDownWithError() throws {
        if testRun?.failureCount ?? 0 > 0 {
            let screenshot = XCTAttachment(screenshot: app.screenshot())
            screenshot.name = "Failure screenshot"
            screenshot.lifetime = .keepAlways
            add(screenshot)

            let hierarchy = XCTAttachment(string: app.debugDescription)
            hierarchy.name = "Failure UI hierarchy"
            hierarchy.lifetime = .keepAlways
            add(hierarchy)
        }
        _ = try? authCall("DELETE", "/_test/sessions/\(authSession)")
        try super.tearDownWithError()
    }

    private func waitForExistence(
        _ element: XCUIElement,
        named name: String = "Element",
        timeout: TimeInterval? = nil,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertTrue(
            element.waitForExistence(timeout: timeout ?? defaultTimeout),
            "\(name) did not exist before the timeout.\n\(element.debugDescription)",
            file: file,
            line: line
        )
    }

    private func waitForHittability(
        _ element: XCUIElement,
        named name: String = "Element",
        timeout: TimeInterval? = nil,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertTrue(
            element.wait(for: \.isHittable, toEqual: true, timeout: timeout ?? defaultTimeout),
            "\(name) was not visible and hittable before the timeout.\n\(element.debugDescription)",
            file: file,
            line: line
        )
    }

    private func waitForAbsence(
        _ element: XCUIElement,
        named name: String = "Element",
        timeout: TimeInterval? = nil,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertTrue(
            element.wait(for: \.exists, toEqual: false, timeout: timeout ?? defaultTimeout),
            "\(name) still existed after the timeout.\n\(element.debugDescription)",
            file: file,
            line: line
        )
    }

    private func replaceText(in element: XCUIElement, with text: String) {
        element.tap()
        if let currentValue = element.value as? String, !currentValue.isEmpty {
            element.typeText(String(repeating: XCUIKeyboardKey.delete.rawValue, count: currentValue.count))
        }
        if !text.isEmpty {
            element.typeText(text)
        }
    }

    private func pressBack() {
        let backButton = app.navigationBars.buttons.element(boundBy: 0)
        if backButton.exists, backButton.isHittable {
            backButton.tap()
        } else {
            app.swipeRight()
        }
    }

    func testSwipeDelete() throws {
        let email = app.descendants(matching: .any)["signIn.email"]
        waitForHittability(email, named: "email", timeout: 10.0)
        replaceText(in: email, with: "user@example.com")
        let password = app.descendants(matching: .any)["signIn.password"]
        waitForHittability(password, named: "password", timeout: 5.0)
        replaceText(in: password, with: "example-password")
        let submit = app.descendants(matching: .any)["signIn.submit"]
        waitForHittability(submit, named: "submit", timeout: 5.0)
        submit.tap()
        let count = app.descendants(matching: .any)["tasks.count"]
        waitForHittability(count, named: "count", timeout: 10.0)
        let count2 = app.descendants(matching: .any).matching(identifier: "tasks.count").matching(NSPredicate(format: "label CONTAINS %@", "25 tasks")).firstMatch
        waitForHittability(count2, named: "count2", timeout: 5.0)
        let task025Row = app.descendants(matching: .any)["tasks.row.task-025"]
        waitForHittability(task025Row, named: "task025Row", timeout: 5.0)
        task025Row.swipeLeft()
        let delete = app.descendants(matching: .any).matching(NSPredicate(format: "label == %@", "Delete")).firstMatch
        waitForHittability(delete, named: "delete", timeout: 5.0)
        delete.tap()
        waitForAbsence(task025Row, named: "task025Row", timeout: 5.0)
        let count3 = app.descendants(matching: .any).matching(identifier: "tasks.count").matching(NSPredicate(format: "label CONTAINS %@", "24 tasks")).firstMatch
        waitForHittability(count3, named: "count3", timeout: 5.0)
    }
}
